    border: 1px solid var(--line); border-radius: 18px;
    background: rgba(255, 255, 255, 0.02);
    overflow: hidden; text-align: center;
  }
  .math-bar div { padding: 22px 18px; border-right: 1px solid var(--line); }
  .math-bar div:last-child { border-right: 0; }
  .math-bar b {
    display: block; font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 800; font-size: clamp(22px, 2.6vw, 30px);
    background: var(--grad-brand);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
    letter-spacing: -0.02em; margin-bottom: 4px;
  }
  .math-bar span { font-size: 12.5px; color: var(--fg-muted); }
  @media (max-width: 700px) {
    .math-bar { grid-template-columns: 1fr; }
    .math-bar div { border-right: 0; border-bottom: 1px solid var(--line); }
    .math-bar div:last-child { border-bottom: 0; }
  }

  /* ---- Sticky bottom CTA bar ---- */
  .sticky-cta {
    position: fixed; left: 50%; bottom: 18px;
    transform: translate(-50%, 30px); z-index: 75;
    background: rgba(13, 14, 22, 0.92);
    backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
    border: 1px solid var(--line-2); border-radius: 16px;
    padding: 10px 14px 10px 18px;
    display: flex; align-items: center; gap: 14px;
    box-shadow: 0 30px 80px -20px rgba(0, 0, 0, 0.7), 0 0 0 1px rgba(255, 209, 102, 0.15);
    opacity: 0;
    transition: opacity 0.3s ease, transform 0.3s ease;
    pointer-events: none; max-width: calc(100vw - 32px);
  }
  .sticky-cta.show { opacity: 1; transform: translate(-50%, 0); pointer-events: auto; }
  .sticky-cta-text { font-size: 13.5px; color: var(--fg); line-height: 1.3; }
  .sticky-cta-text b { color: #ffe096; font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 700; }
  .sticky-cta-text span { display: block; font-size: 11.5px; color: var(--fg-muted); }
  .sticky-cta .btn { height: 42px; padding: 0 18px; font-size: 14px; }
  @media (max-width: 600px) {
    .sticky-cta { left: 12px; right: 12px; bottom: 12px; transform: translateY(30px); }
    .sticky-cta.show { transform: translateY(0); }
    .sticky-cta-text { font-size: 12px; }
    .sticky-cta-text span { display: none; }
  }

  /* ---- Mini countdown inside hero ---- */
  .hero-cd {
    display: inline-flex; align-items: center; gap: 10px;
    margin-top: 18px; padding: 10px 14px;
    border-radius: 12px;
    background: rgba(255, 91, 108, 0.08);
    border: 1px solid rgba(255, 91, 108, 0.25);
    font-size: 13.5px; color: var(--fg-muted);
  }
  .hero-cd .pulse {
    width: 8px; height: 8px; border-radius: 999px;
    background: var(--danger);
    box-shadow: 0 0 0 0 rgba(255, 91, 108, 0.6);
    animation: dotpulse 1.6s infinite; flex-shrink: 0;
  }
  .hero-cd b {
    font-variant-numeric: tabular-nums; color: #fff;
    font-family: 'JetBrains Mono', monospace;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 6px; padding: 2px 8px; margin: 0 2px;
  }

  /* ---- "What it costs everywhere else" comparison strip ---- */
  .price-strip {
    border: 1px solid var(--line); border-radius: 20px;
    padding: 28px clamp(18px, 3vw, 32px);
    background: rgba(255, 255, 255, 0.02); margin-top: 30px;
  }
  .price-strip h3 { font-size: 20px; margin-bottom: 18px; color: var(--fg); }
  .price-strip h3 .lo { color: var(--fg-muted); font-weight: 500; font-size: 14.5px; display: block; margin-top: 4px; letter-spacing: 0; }
  .price-rows { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 18px; }
  .price-rows .row {
    display: flex; justify-content: space-between; align-items: center;
    padding: 10px 14px; border-radius: 10px;
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid var(--line); font-size: 14px;
  }
  .price-rows .row.you {
    background: linear-gradient(90deg, rgba(255, 209, 102, 0.10), rgba(108, 140, 255, 0.10));
    border-color: rgba(255, 209, 102, 0.4);
  }
  .price-rows .row .lbl { color: var(--fg); }
  .price-rows .row .px { color: var(--fg-muted); font-family: 'JetBrains Mono', monospace; font-weight: 600; }
  .price-rows .row.you .px {
    background: linear-gradient(135deg, #ffd166, #a3ff66);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent; font-weight: 800;
  }
  @media (max-width: 700px) { .price-rows { grid-template-columns: 1fr; } }

  /* ---- Guarantee strip (used inside dollar-card) ---- */
  .guarantee-strip {
    margin-top: 36px;
    display: grid; grid-template-columns: 80px 1fr;
    gap: 22px; align-items: center;
    padding: 22px 26px; border-radius: 18px;
    background: rgba(255, 209, 102, 0.06);
    border: 1px solid rgba(255, 209, 102, 0.22);
  }
  .guarantee-strip .seal {
    width: 80px; height: 80px; border-radius: 50%;
    background: var(--grad-fire); display: grid; place-items: center;
    color: #1c0205;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 900; font-size: 14px; line-height: 1.05; text-align: center;
    box-shadow: 0 14px 36px -10px rgba(255, 181, 71, 0.5);
  }
  .guarantee-strip h4 { font-size: 17px; margin-bottom: 4px; color: #fff; }
  .guarantee-strip p { font-size: 13.5px; color: var(--fg-muted); line-height: 1.55; }
  @media (max-width: 600px) { .guarantee-strip { grid-template-columns: 1fr; text-align: center; } .guarantee-strip .seal { margin: 0 auto; } }

  /* =====================================================================
     NEW, Aggressive sections
     ===================================================================== */

  /* ---- Real trust badges strip (replaces fake press strip) ---- */
  .trust-strip {
    margin-top: 56px;
    padding: 26px clamp(18px, 3vw, 32px);
    border: 1px solid var(--line);
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.02);
  }
  .trust-strip-title {
    text-align: center;
    font-size: 11.5px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--fg-dim);
    font-weight: 700;
    margin-bottom: 18px;
  }
  .trust-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
    align-items: stretch;
  }
  .trust-card {
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 14px 12px;
    background: rgba(255, 255, 255, 0.025);
    display: flex;
    flex-direction: column;
    gap: 6px;
    align-items: center;
    justify-content: center;
    text-align: center;
    transition: border-color 0.2s, transform 0.2s;
  }
  .trust-card:hover { border-color: var(--line-2); transform: translateY(-2px); }
  .trust-card .tc-icon {
    width: 32px; height: 32px;
    display: grid; place-items: center;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.05);
    color: #c2d0ff;
  }
  .trust-card .tc-icon svg { width: 18px; height: 18px; }
  .trust-card .tc-label {
    font-size: 12px;
    color: var(--fg);
    font-weight: 600;
    line-height: 1.2;
  }
  .trust-card .tc-sub {
    font-size: 10.5px;
    color: var(--fg-dim);
    line-height: 1.2;
  }
  .trust-card.tc-tp .tc-icon { background: rgba(0, 182, 122, 0.14); color: #43e3a5; }
  .trust-card.tc-ph .tc-icon { background: rgba(255, 99, 71, 0.14); color: #ff8c70; }
  .trust-card.tc-g2 .tc-icon { background: rgba(255, 92, 92, 0.14); color: #ff8585; }
  .trust-card.tc-st .tc-icon { background: rgba(108, 140, 255, 0.16); color: #a3b4ff; }
  .trust-card.tc-soc .tc-icon { background: rgba(56, 225, 255, 0.14); color: #66ecff; }
  .trust-card.tc-mb .tc-icon { background: rgba(255, 209, 102, 0.14); color: #ffe096; }
  @media (max-width: 900px) { .trust-grid { grid-template-columns: repeat(3, 1fr); } }
  @media (max-width: 480px) { .trust-grid { grid-template-columns: repeat(2, 1fr); } }

  /* ---- Value stack section ---- */
  .stack-card {
    border: 1px solid var(--line-2);
    border-radius: 24px;
    padding: 36px clamp(22px, 4vw, 44px);
    background:
      radial-gradient(60% 60% at 100% 0%, rgba(255, 209, 102, 0.10), transparent 70%),
      radial-gradient(60% 60% at 0% 100%, rgba(108, 140, 255, 0.10), transparent 70%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.005));
    overflow: hidden;
  }
  .stack-list {
    margin: 22px auto 0;
    display: grid;
    gap: 8px;
    max-width: 900px;
  }
  .stack-row {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    gap: 18px;
    padding: 14px 18px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.02);
    transition: border-color 0.2s, transform 0.2s;
  }
  .stack-row:hover { border-color: var(--line-2); transform: translateX(2px); }
  .stack-row .sl { display: flex; align-items: flex-start; gap: 12px; }
  .stack-row .sl .num {
    width: 26px; height: 26px;
    border-radius: 50%;
    background: rgba(255, 209, 102, 0.14);
    border: 1px solid rgba(255, 209, 102, 0.3);
    color: #ffe096;
    display: grid; place-items: center;
    font-size: 11.5px; font-weight: 700;
    font-family: 'Plus Jakarta Sans', sans-serif;
    flex-shrink: 0;
  }
  .stack-row .sl b { color: #fff; font-size: 14.5px; display: block; margin-bottom: 2px; }
  .stack-row .sl span { color: var(--fg-muted); font-size: 12.5px; line-height: 1.5; display: block; }
  .stack-row .sr {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    color: #ffe096;
    background: rgba(255, 209, 102, 0.08);
    border: 1px solid rgba(255, 209, 102, 0.22);
    padding: 6px 12px;
    border-radius: 8px;
    white-space: nowrap;
  }
  .stack-row.priceless .sr {
    color: #c2d0ff;
    background: rgba(108, 140, 255, 0.08);
    border-color: rgba(108, 140, 255, 0.22);
  }
  .stack-totals {
    margin-top: 26px;
    border-radius: 18px;
    padding: 24px 26px;
    background: linear-gradient(90deg, rgba(255, 209, 102, 0.10), rgba(108, 140, 255, 0.10));
    border: 1px solid rgba(255, 209, 102, 0.35);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 22px;
    align-items: center;
  }
  .stack-totals .st-l { font-size: 14px; color: var(--fg-muted); line-height: 1.5; }
  .stack-totals .st-l b { color: #fff; display: block; font-size: 19px; margin-bottom: 4px; }
  .stack-totals .st-l s { color: var(--fg-dim); }
  .stack-totals .st-r {
    text-align: right;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 900;
    font-size: clamp(40px, 6vw, 64px);
    line-height: 1;
    background: linear-gradient(135deg, #ffd166 0%, #a3ff66 50%, #38e1ff 100%);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
    letter-spacing: -0.04em;
  }
  .stack-totals .st-r small { display: block; font-size: 13px; color: var(--fg-muted); margin-top: 6px; -webkit-text-fill-color: var(--fg-muted); font-weight: 500; letter-spacing: 0; font-family: Inter, sans-serif; }
  @media (max-width: 760px) {
    .stack-row { grid-template-columns: 1fr; gap: 8px; }
    .stack-row .sr { justify-self: start; }
    .stack-totals { grid-template-columns: 1fr; text-align: left; }
    .stack-totals .st-r { text-align: left; }
  }

  /* ---- Day 0 / 7 / 14 timeline ---- */
  .timeline-section {
    padding-block: 60px 30px;
  }
  .timeline-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-top: 36px;
    max-width: 1100px;
    margin-left: auto;
    margin-right: auto;
    position: relative;
  }
  .timeline-grid::before {
    content: '';
    position: absolute;
    left: 6%;
    right: 6%;
    top: 76px;
    height: 2px;
    background: linear-gradient(90deg,
      rgba(255, 209, 102, 0.5) 0%,
      rgba(163, 255, 102, 0.5) 50%,
      rgba(56, 225, 255, 0.5) 100%);
    pointer-events: none;
    z-index: 0;
  }
  .timeline-card {
    position: relative;
    border: 1px solid var(--line);
    border-radius: 20px;
    padding: 28px 26px 26px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.025), rgba(255, 255, 255, 0.005));
    backdrop-filter: blur(10px);
    z-index: 1;
  }
  .timeline-card .tl-marker {
    width: 56px; height: 56px;
    border-radius: 50%;
    display: grid; place-items: center;
    margin: 0 auto 14px;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 800;
    font-size: 14px;
    line-height: 1;
    text-align: center;
    color: #1c0205;
    position: relative;
    z-index: 2;
  }
  .timeline-card.t1 { border-color: rgba(255, 209, 102, 0.35); }
  .timeline-card.t1 .tl-marker { background: linear-gradient(135deg, #ffd166, #ffb547); box-shadow: 0 12px 30px -8px rgba(255, 181, 71, 0.4); }
  .timeline-card.t2 { border-color: rgba(163, 255, 102, 0.35); }
  .timeline-card.t2 .tl-marker { background: linear-gradient(135deg, #a3ff66, #5dffae); box-shadow: 0 12px 30px -8px rgba(93, 255, 174, 0.4); }
  .timeline-card.t3 { border-color: rgba(56, 225, 255, 0.35); }
  .timeline-card.t3 .tl-marker { background: linear-gradient(135deg, #38e1ff, #6c8cff); box-shadow: 0 12px 30px -8px rgba(56, 225, 255, 0.4); color: #061629; }
  .timeline-card .tl-marker b { font-size: 18px; display: block; }
  .timeline-card h4 {
    text-align: center;
    font-size: 18px;
    color: #fff;
    margin-bottom: 6px;
    font-family: 'Plus Jakarta Sans', sans-serif;
  }
  .timeline-card .tl-sub {
    text-align: center;
    font-size: 12.5px;
    color: var(--fg-muted);
    font-style: italic;
    margin-bottom: 18px;
  }
  .timeline-card ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    gap: 10px;
  }
  .timeline-card li {
    display: grid;
    grid-template-columns: 18px 1fr;
    gap: 10px;
    align-items: flex-start;
    font-size: 13.5px;
    color: var(--fg);
    line-height: 1.5;
  }
  .timeline-card li .tl-check {
    display: grid; place-items: center;
    width: 18px; height: 18px;
    border-radius: 5px;
    font-size: 11px;
    font-weight: 800;
    color: #061629;
    margin-top: 2px;
  }
  .timeline-card.t1 li .tl-check { background: linear-gradient(135deg, #ffd166, #ffb547); }
  .timeline-card.t2 li .tl-check { background: linear-gradient(135deg, #a3ff66, #5dffae); }
  .timeline-card.t3 li .tl-check { background: linear-gradient(135deg, #38e1ff, #6c8cff); }
  @media (max-width: 900px) {
    .timeline-grid { grid-template-columns: 1fr; gap: 14px; }
    .timeline-grid::before { display: none; }
  }

  /* ---- Triple guarantee section ---- */
  .triple-card {
    border: 1px solid rgba(255, 209, 102, 0.35);
    border-radius: 28px;
    padding: 44px clamp(24px, 4vw, 56px);
    background:
      radial-gradient(60% 60% at 50% 0%, rgba(255, 209, 102, 0.16), transparent 70%),
      radial-gradient(80% 60% at 50% 100%, rgba(163, 255, 102, 0.10), transparent 70%),
      linear-gradient(180deg, #11131c 0%, #0a0c14 100%);
    position: relative; overflow: hidden;
    text-align: center;
  }
  .triple-card .ribbon-top {
    display: inline-flex; align-items: center; gap: 8px;
    background: var(--grad-fire); color: #1c0205;
    font-weight: 800; font-size: 12px; letter-spacing: 0.08em;
    text-transform: uppercase; padding: 6px 14px;
    border-radius: 999px; margin-bottom: 18px;
  }
  .triple-card .ribbon-top::before {
    content: ''; width: 6px; height: 6px;
    border-radius: 50%; background: #1c0205;
  }
  .triple-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 32px;
    text-align: left;
  }
  .triple-tile {
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 24px 22px;
    background: rgba(255, 255, 255, 0.025);
    position: relative;
  }
  .triple-tile .gnum {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 800;
    font-size: 11.5px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #ffe096;
    margin-bottom: 12px;
  }
  .triple-tile .gnum::before {
    content: '';
    width: 22px; height: 22px;
    border-radius: 50%;
    background: linear-gradient(135deg, #ffd166, #ffb547);
    color: #1c0205;
    display: grid; place-items: center;
    font-size: 11px;
  }
  .triple-tile h4 { font-size: 18px; margin-bottom: 8px; color: #fff; line-height: 1.3; }
  .triple-tile p { font-size: 13.5px; color: var(--fg-muted); line-height: 1.55; }
  .triple-tile.t-fifty { border-color: rgba(163, 255, 102, 0.4); background: linear-gradient(180deg, rgba(163, 255, 102, 0.07), rgba(163, 255, 102, 0.015)); }
  .triple-tile.t-fifty .gnum { color: #c4ff96; }
  .triple-tile.t-fifty .gnum::before { background: linear-gradient(135deg, #a3ff66, #5dffae); }
  .triple-bottom {
    margin-top: 28px;
    padding: 20px 24px;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--line);
    font-size: 14px;
    color: var(--fg);
    text-align: left;
    line-height: 1.6;
  }
  .triple-bottom b { color: #fff; }
  @media (max-width: 900px) { .triple-grid { grid-template-columns: 1fr; } }

  /* ---- Anonymous authority "Off-the-record" wall ---- */
  .offrec-card {
    border: 1px solid var(--line-2);
    border-radius: 24px;
    padding: 36px clamp(22px, 4vw, 44px);
    background:
      radial-gradient(60% 60% at 100% 0%, rgba(108, 140, 255, 0.10), transparent 70%),
      radial-gradient(60% 60% at 0% 100%, rgba(160, 107, 255, 0.10), transparent 70%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.005));
  }
  .offrec-grid {
    margin-top: 26px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
  }
  .offrec-tile {
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 22px 20px;
    background: rgba(255, 255, 255, 0.025);
    position: relative;
  }
  .offrec-tile::before {
    content: '"';
    position: absolute;
    top: 6px; right: 18px;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-weight: 800;
    font-size: 60px;
    line-height: 1;
    color: rgba(108, 140, 255, 0.2);
  }
  .offrec-tile blockquote {
    color: var(--fg);
    font-size: 14.5px;
    line-height: 1.6;
    margin: 0 0 14px 0;
    position: relative;
    z-index: 1;
  }
  .offrec-tile .or-meta {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-top: 12px;
    border-top: 1px solid var(--line);
  }
  .offrec-tile .or-redact {
    width: 36px; height: 36px;
    border-radius: 50%;
    background: rgba(108, 140, 255, 0.14);
    border: 1px solid rgba(108, 140, 255, 0.3);
    display: grid; place-items: center;
    color: #a3b4ff;
    font-size: 14px;
    font-weight: 700;
    flex-shrink: 0;
    position: relative;
  }
  .offrec-tile .or-redact svg { width: 16px; height: 16px; }
  .offrec-tile .or-role {
    font-size: 13px;
    color: var(--fg);
    line-height: 1.3;
  }
  .offrec-tile .or-role b { display: block; color: #fff; font-size: 13.5px; }
  .offrec-tile .or-role span { color: var(--fg-dim); font-size: 11.5px; }
  .offrec-disclaimer {
    margin-top: 24px;
    padding: 14px 18px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.02);
    border: 1px dashed var(--line);
    font-size: 12.5px;
    color: var(--fg-muted);
    line-height: 1.55;
    text-align: center;
  }
  .offrec-disclaimer b { color: var(--fg); }
  @media (max-width: 900px) { .offrec-grid { grid-template-columns: 1fr; } }

  /* ---- Loss aversion calculator ---- */
  .loss-card {
    border: 1px solid rgba(255, 91, 108, 0.3);
    border-radius: 24px;
    padding: 36px clamp(22px, 4vw, 44px);
    background:
      radial-gradient(60% 60% at 100% 0%, rgba(255, 91, 108, 0.10), transparent 70%),
      radial-gradient(60% 60% at 0% 100%, rgba(255, 209, 102, 0.10), transparent 70%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.005));
  }
  .loss-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 28px;
    margin-top: 28px;
    align-items: stretch;
  }
  .loss-col {
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 24px 26px;
