  (function () {
    var sticky = document.querySelector('[data-sticky-cta]');
    if (!sticky || !('IntersectionObserver' in window)) return;
    var top = document.createElement('div');
    top.style.cssText = 'position:absolute;top:700px;left:0;width:1px;height:1px;pointer-events:none;';
    var bot = document.createElement('div');
    bot.style.cssText = 'position:absolute;bottom:240px;left:0;width:1px;height:1px;pointer-events:none;';
    document.body.style.position = document.body.style.position || 'relative';
    document.body.appendChild(top);
    document.body.appendChild(bot);
    var pastTop = false, nearBottom = false;
    function apply() {
      if (pastTop && !nearBottom) sticky.classList.add('show');
      else sticky.classList.remove('show');
    }
    new IntersectionObserver(function (entries) {
      pastTop = entries[0].boundingClientRect.top < 0;
      apply();
    }).observe(top);
    new IntersectionObserver(function (entries) {
      nearBottom = entries[0].isIntersecting;
      apply();
    }).observe(bot);
  })();
