<script defer>
(function () {
  var DURATION = (12 * 3600 + 31 * 60) * 1000;
  var key = 'omnirogue_cd_end';
  var end = parseInt(sessionStorage.getItem(key), 10);
  if (!end || end < Date.now()) { end = Date.now() + DURATION; sessionStorage.setItem(key, end); }
  function pad(n) { return n < 10 ? '0' + n : '' + n; }
  var hs = document.querySelectorAll('[data-cd-h]');
  var ms = document.querySelectorAll('[data-cd-m]');
  var ss = document.querySelectorAll('[data-cd-s]');
  if (!hs.length && !ms.length && !ss.length) return;
  var lastH = '', lastM = '', lastS = '';
  function tick() {
    if (document.hidden) return;
    var diff = Math.max(0, end - Date.now());
    var h = Math.floor(diff / 3600000); diff -= h * 3600000;
    var m = Math.floor(diff / 60000);   diff -= m * 60000;
    var s = Math.floor(diff / 1000);
    var ph = pad(h), pm = pad(m), ps = pad(s);
    if (ph !== lastH) { hs.forEach(function(el){ el.textContent = ph; }); lastH = ph; }
    if (pm !== lastM) { ms.forEach(function(el){ el.textContent = pm; }); lastM = pm; }
    if (ps !== lastS) { ss.forEach(function(el){ el.textContent = ps; }); lastS = ps; }
  }
  tick();
  setInterval(tick, 1000);
  document.addEventListener('visibilitychange', function(){ if (!document.hidden) tick(); });
})();
</script>
